class Glyph {
  constructor(public char: string, public font: string) {}
  draw(ctx: CanvasRenderingContext2D, x: number, y: number) {
    ctx.font = this.font;
    ctx.fillText(this.char, x, y);
  }
}

const cache: Map<string, Glyph> = new Map();

function getGlyph(char: string, font: string) {
  const key = char + '|' + font;
  if (!cache.has(key)) cache.set(key, new Glyph(char, font));
  return cache.get(key)!;
}

class Glyph { constructor(public char: string, public font: string) {} }
class TextLayout {
  render(text: string, font: string) {
    const result: Glyph[] = [];
    for (const c of text) {
      const g = new Glyph(c, font);
      result.push(g); // many allocations per render
    }
    return result;
  }
}

