const poolB = new Map<string,GlyphB>();
function getGlyphB(char:string,font:string){ const k=char+'|'+font; if(!poolB.has(k)) poolB.set(k,new GlyphB(char,font)); return poolB.get(k)!; }
function renderB(text:string,font:string){ for(let i=0;i<text.length;i++){ const g=getGlyphB(text[i],font); g.x=i*10; g.y=0; g.draw(null); } }
